#!/usr/bin/env bash
set -euo pipefail

BLUE='\033[1;34m'
GREEN='\033[1;32m'
NC='\033[0m'

info() { echo -e "${BLUE}ℹ${NC} $1"; }
ok() { echo -e "${GREEN}✓${NC} $1"; }

info "Checking environment..."

if [ -f "uv.toml" ]; then
    rm -f uv.toml
fi

if [ -f "/etc/os-release" ] && grep -q "rodete" /etc/os-release; then
    info "Detected Rodete (Internal Linux). Configuring public PyPI registry for uv..."

    cat <<EOF > uv.toml
# Auto-generated by tools/scripts/setup-env.sh for Rodete compatibility
[[index]]
url = "https://pypi.org/simple"
default = true
EOF
    ok "Created uv.toml with public PyPI index"
else
    info "Standard environment detected. Using default registry configurations."
fi
